{
  "technical_and_design_decisions": [
    "All new modules and features will be built on Spring Framework 6.0 and Java 17+ to align with the framework's current version requirements.",
    "Kafka starting offset control will use a stream-scoped metadata store to persist committed offsets, with user-specified start offsets only applied on initial stream deployment unless an explicit reset is triggered by the user.",
    "Kafka partition pre-allocation and message bus partition pre-allocation will use static assignment during stream deployment, disabling dynamic rebalancing to meet the requirement of no rebalancing on crash or redeployment.",
    "The reactor-stream processor will integrate directly with Project Reactor's Flux API, leveraging XD's existing module lifecycle and metrics hooks for consistency with other XD modules.",
    "Microbatching will be implemented as a configurable mode in the XD source module runtime, using a time-based and size-based buffer to emit batches to downstream modules.",
    "The Spark POC will use Spring for Apache Spark integration to maintain alignment with the existing Spring ecosystem, with initial testing on a standalone Spark cluster before cloud cluster testing.",
    "Performance testing infrastructure will use Rackspace Cloud Servers with dedicated clusters for Kafka, XD, and load generation, paired with open-source monitoring and load testing tools."
  ],
  "assumptions": [
    "Existing Spring XD core runtime, module framework, deployment orchestration, and Kafka client integration codebases are available, well-documented, and can be extended without full rewrites.",
    "A Rackspace cloud account with sufficient quota for provisioning test servers (Kafka brokers, XD nodes, load generators) is already available and accessible to the development team.",
    "The target Kafka version for the increment is 3.x, which supports the static partition assignment and offset management APIs required for the Kafka-related user stories.",
    "The existing XD documentation wiki platform (e.g., Confluence) is available and accessible for updating with new feature guides.",
    "Open-source load testing tools (e.g., JMeter, Gatling) are already licensed for use in the performance testing infrastructure.",
    "The Spark POC evaluation will prioritize compatibility with XD's existing module and messaging architecture over custom Spark-specific integrations.",
    "User-specified start offsets for Kafka sources will be validated to be non-negative and within the topic's current offset range to prevent invalid deployment configurations."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Kafka Source Starting Offset Control Implementation",
      "activity_description": "Modify existing Kafka source module to support configurable start offset parameter, integrate with XD metadata store to persist committed offsets across crashes, implement logic to apply start offset only on initial stream deployment (or explicit user reset), add input validation for offset values, and include unit tests for offset handling logic.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "Kafka Source Partition Pre-Allocation Implementation",
      "activity_description": "Update stream deployment orchestration logic to assign fixed Kafka partitions to each Kafka source module instance during stream deployment, disable dynamic consumer group rebalancing for stream-associated Kafka consumers, add configuration options for custom partition assignment strategies, and include integration tests to validate fixed partition assignment.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A3",
      "activity_name": "Message Bus Partition Pre-Allocation Implementation",
      "activity_description": "Modify XD core message bus to pre-allocate partitions/queues to specific XD nodes during stream deployment, implement node affinity for stream modules to prevent rebalancing on node crash or redeployment, add configuration options for partition allocation rules, and include integration tests for failover and redeployment scenarios.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A4",
      "activity_name": "Reactor-Stream Processor Module Development",
      "activity_description": "Develop new XD processor module integrating Project Reactor Flux API, implement configuration options for time window duration, source field extraction, and aggregation expressions (min, avg, etc.), integrate with XD module lifecycle and metrics framework, and include unit and integration tests for time window aggregation logic.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A5",
      "activity_name": "Microbatching Capability Implementation",
      "activity_description": "Modify XD source module runtime to support configurable microbatching, implement message buffer that accumulates messages based on configurable batch interval and max batch size, emit message batches to downstream modules, add configuration options for batch parameters, update existing core source modules to support microbatching mode, and include integration tests for batch emission behavior.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "A6",
      "activity_name": "Spark for XD POC and Design",
      "activity_description": "Research Spring for Apache Spark integration patterns compatible with XD architecture, develop proof-of-concept Spark streaming module for XD, test end-to-end data flow from XD sources to Spark processing, document recommended design and implementation approach for full Spark XD integration, and include test results and performance benchmarks from the POC.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A7",
      "activity_name": "Performance Testing Infrastructure Setup",
      "activity_description": "Provision Rackspace cloud servers for Kafka cluster, XD cluster, and load generation nodes, install and configure Kafka, XD, and monitoring tools (Prometheus, Grafana), develop automated test scripts for Kafka baseline testing and XD use case benchmarking, and run smoke tests to validate infrastructure functionality.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A8",
      "activity_name": "Wiki Documentation Update",
      "activity_description": "Write configuration and usage guides for all new features (Kafka offset control, partition pre-allocation, reactor-stream processor, microbatching, Spark POC), add practical usage examples for each feature, and update XD module development documentation to reflect changes to the module runtime.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration and System Testing",
      "activity_description": "Conduct end-to-end integration testing of all new increment features, test combined usage of multiple new features in stream deployments, validate crash recovery and redeployment behavior for offset and partition management features, verify microbatching and reactor-stream processor functionality in production-like scenarios, and resolve all identified bugs.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 272
  }
}

